import {ChatHistory,playerName,chatText} from './chat-history.js';
export {playerName,chatText};
export const QUICK_CHATS=Object.freeze(['I got it!','Defending!','Need boost!','Nice shot!','Thanks!','Sorry!','Cuck puppy','Your my good girl.','That is not right puppy',"I’m sorry kitten",'CHAT CLIP THAAAAATTTTT...','In your net!',"I’m gonna touch it if you don’t!",'W coms mum','Not know kitten whiker']);
export function quickChats(value){return (Array.isArray(value)?value:QUICK_CHATS).map(chatText).filter(Boolean).slice(0,20);}
export function setupSocialUI(settings,{save=()=>{},send=()=>false,profile=()=>{},opened=()=>{},historyOptions={}}={},root=document){
 const node=id=>root.getElementById(id);settings.username=playerName(settings.username);settings.quickChats=quickChats(settings.quickChats);
 function renderHistory(state){for(const id of ['chat-feed','chat-log']){const feed=node(id);feed.replaceChildren();for(const entry of state.messages){const line=root.createElement('p'),label=root.createElement('strong'),body=root.createElement('span');label.textContent=entry.name+': ';body.textContent=entry.text;line.append(label,body);feed.append(line);}feed.hidden=!state.messages.length;}}
 const history=new ChatHistory({...historyOptions,onChange:renderHistory});
 function presets(){const grid=node('quick-chat-buttons');grid.replaceChildren();for(const text of settings.quickChats){const button=root.createElement('button');button.type='button';button.textContent=text;button.className='secondary';button.addEventListener('click',()=>submit(text));grid.append(button);}node('custom-quick-chats').value=settings.quickChats.join('\n');}
 function submit(value){const text=chatText(value);if(!text)return;if(send(text)){node('chat-text').value='';node('chat-dialog').close();}else node('chat-status').textContent='Please wait a moment before sending another message.';}
 function commitName(value){settings.username=playerName(value);node('display-name').value=settings.username;node('username-input').value=settings.username;const saved=save()!==false;profile(settings.username);node('profile-status').textContent=saved?'Saved locally in this browser.':'Name changed for this session. This browser blocked local saving.';node('profile-feedback').textContent=saved?'SAVED LOCALLY':'SESSION ONLY';node('profile-feedback').hidden=false;return saved;}
 node('chat-send').addEventListener('click',()=>submit(node('chat-text').value));node('chat-form').addEventListener('submit',event=>{event.preventDefault();submit(node('chat-text').value);});node('chat-back').addEventListener('click',()=>node('chat-dialog').close());
 node('display-name').value=settings.username;node('display-name').addEventListener('change',()=>commitName(node('display-name').value));
 node('profile-form').addEventListener('submit',event=>{event.preventDefault();if(!node('username-input').value.trim()){node('profile-status').textContent='Enter a username.';node('username-input').focus();return;}if(commitName(node('username-input').value))node('profile-dialog').close();});node('profile-cancel').addEventListener('click',()=>node('profile-dialog').close());
 node('custom-quick-chats').addEventListener('change',()=>{settings.quickChats=quickChats(node('custom-quick-chats').value.split('\n'));presets();save();});node('reset-quick-chats').addEventListener('click',()=>{settings.quickChats=quickChats();presets();save();});presets();
 return {receive:message=>history.add(message),setHistory:state=>history.replace(state),reset:()=>history.clear(),dispose:()=>history.dispose(),openProfile(){opened();node('username-input').value=settings.username;node('profile-status').textContent='Your username is saved on this browser/device.';if(!node('profile-dialog').open)node('profile-dialog').showModal();node('username-input').focus();node('username-input').select?.();},open(quick=false,online=false){opened();node('chat-status').textContent=(online?'ALL PLAYERS':'OFFLINE · LOCAL CHAT')+' · NEWEST 5 MESSAGES · CLEARS EVERY 5 MINUTES';node('chat-title').textContent=quick?'QUICK CHAT':'TEXT CHAT';if(!node('chat-dialog').open)node('chat-dialog').showModal();(quick?node('quick-chat-buttons').querySelector('button'):node('chat-text'))?.focus();}};
}

export function setupSocialAccess({ui,started=()=>false,paused=()=>false,phase=()=>'',online=()=>false,closePause=()=>{},returnToPause=()=>{},focusGame=()=>{},skipReplay=()=>{}},root=document,keys=window){
 const node=id=>root.getElementById(id),bindings=[];function listen(target,type,fn){target.addEventListener(type,fn);bindings.push([target,type,fn]);}
 for(const id of ['profile-edit','pause-profile-button'])listen(node(id),'click',()=>{if(paused())closePause();ui.openProfile();});
 for(const id of ['chat-button','hud-chat-button','pause-chat-button','room-chat-button','party-chat-button','result-chat-button'])listen(node(id),'click',()=>{if(paused())closePause();ui.open(false,online());});
 for(const id of ['chat-dialog','profile-dialog'])listen(node(id),'close',()=>{if(node(id).open)return;if(started()&&!root.querySelector('dialog[open]')){if(paused())returnToPause();else focusGame();}else if(!started()&&!root.querySelector('dialog[open]'))node('profile-edit').focus();});
 listen(keys,'keydown',event=>{if(event.code!=='Enter'||event.repeat||!started()||paused()||root.querySelector('dialog[open]')||/INPUT|SELECT|TEXTAREA|BUTTON/.test(event.target?.tagName))return;if(phase()==='goal'){event.preventDefault();skipReplay();}else if(phase()!=='ended'){event.preventDefault();ui.open(false,online());}});
 return {dispose(){for(const [target,type,fn]of bindings)target.removeEventListener(type,fn);}};
}
